// DOM helpers for the sign-in/setup surface. Text from accounts is never HTML.
export function renderGate({user,role,status,empty,error,ready},escape){
  if(!ready)return `<h1>Seven Seas</h1><p>${escape(error||'Connecting to your fleet…')}</p>${error?'<button id="retry-cloud">Try again</button>':''}`;
  if(!user)return `<p class="eyebrow">WELCOME ABOARD</p><h1>Your fleet awaits.</h1><p>Sign in to sail with your group. Ship changes will be shared across your devices.</p><button id="google-login" class="primary">Sign in with Google</button>${error?`<p class="red" role="alert">${escape(error)}</p>`:''}<details><summary>Previous playtest data</summary><p>Your old device-only fleet has not been changed or uploaded.</p><button id="export-local">Export old playtest backup</button></details>`;
  if(!role)return `<h1>Welcome aboard.</h1><p>Signed in as ${escape(user.displayName||user.email||'Player')}. ${escape(error||'Checking group access…')}</p><p>Your account ID:</p><input aria-label="Your account ID" readonly value="${escape(user.uid)}"><p class="subtle">Send this ID to the fleet owner to arrange access. For the first owner, use the Firebase setup instructions.</p><div class="actions"><button id="retry-cloud">Check access again</button><button id="cloud-logout">Sign out</button></div>`;
  if(empty)return `<h1>The fleet is ready.</h1><p>${['owner','admin'].includes(role)?'Create the shared Sea Wren with the agreed starting values. Your old local playtest remains separate.':'The owner or GM needs to add your first vessel.'}</p>${['owner','admin'].includes(role)?'<button id="seed-fleet" class="primary">Create shared Sea Wren</button>':''}${error?`<p class="red">${escape(error)}</p>`:''}`;
  return `<h1>Connecting to your fleet…</h1><p>${escape(error||status)}</p><button id="retry-cloud">Try again</button>`;
}
